SINA_SMART["term1-skin"] = {"lecture":"term1-skin","title":"Integumentary system terminology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"term1-skin:e0","text":"Integument = to cover; skin is the largest organ.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"term1-skin:e1","text":"Skin functions: protection, waterproofing, immune barrier, touch, vitamin D.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"term1-skin:e2","text":"Skin: cutane/o, dermat/o, derm/o; sebum: seb/o; sweat: hidr/o; hair: pil/o; nail: onych/o, ungu/o.","topic":"Structures and combining forms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"term1-skin:e3","text":"hirsut/o hairy; kerat/o horny; melan/o black; myc/o fungus; rhytid/o wrinkle; urtic/o hives; xer/o dry.","topic":"Structures and combining forms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"term1-skin:e4","text":"Acne vulgaris: sebum overproduction, pustules.","topic":"Pathology and lesions","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"term1-skin:e5","text":"Comedo: closed = whitehead; open = blackhead.","topic":"Pathology and lesions","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"term1-skin:e6","text":"Seborrhea = excess sebum.","topic":"Pathology and lesions","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"term1-skin:e7","text":"Macule: flat < 1 cm; papule: small raised; crust: dried serum.","topic":"Pathology and lesions","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1niupn7":"a","z2s5iv":"a","1wjye1d":"a","11u8qj0":"a","da49v8":"a","cljike":"a","er0jre":"a","1ihuwqo":"a","12uhn7d":"a","19emseg":"a","tjpw7k":"a","1ynl1xi":"a","3l9ap1":"a","1horciy":"a","zapzcs":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"term1-skin:e0":{"s":0,"u":["Integument = to cover; skin is the largest organ.","The integumentary system (integument = to cover) is the skin and its related structures.","The skin, about 2 square yards in an adult, is the largest organ : it covers the body, waterproofs it and prevents fluid loss, blocks pathogens (first line of immune defence), is the main receptor for touch, and helps make vitamin D from ultraviolet light while screening harmful UV."],"dp":[]},"term1-skin:e1":{"s":0,"u":["Skin functions: protection, waterproofing, immune barrier, touch, vitamin D.","The skin, about 2 square yards in an adult, is the largest organ : it covers the body, waterproofs it and prevents fluid loss, blocks pathogens (first line of immune defence), is the main receptor for touch, and helps make vitamin D from ultraviolet light while screening harmful UV."],"dp":[{"h":"Why skin is part of immunity","t":"Intact skin is a physical barrier that most pathogens cannot cross, and sebum discourages bacterial growth on its surface. That is why the lecture calls intact skin the first line of defence of the immune system, and why burns and wounds carry such a risk of infection. Source: the lecture's functions of the skin slide."}]},"term1-skin:e2":{"s":1,"u":["Skin: cutane/o, dermat/o, derm/o; sebum: seb/o; sweat: hidr/o; hair: pil/o; nail: onych/o, ungu/o.","Nails ( onych/o, ungu/o ): protect the last bone of each digit; parts: nail body, free edge, lunula, cuticle, nail bed.","Hair ( pil/i, pil/o ): limits heat loss."],"dp":[]},"term1-skin:e3":{"s":1,"u":["hirsut/o hairy; kerat/o horny; melan/o black; myc/o fungus; rhytid/o wrinkle; urtic/o hives; xer/o dry.","More roots: hirsut/o hairy, rough; kerat/o horny, hard; lip/o fat; melan/o black; myc/o fungus; py/o pus; rhytid/o wrinkle; urtic/o rash, hives; xer/o dry; erythr/o red."],"dp":[]},"term1-skin:e4":{"s":2,"u":["Acne vulgaris: sebum overproduction, pustules.","Acne vulgaris ('common acne'): chronic inflammatory disease with pustules from sebum overproduction around the hair shaft, triggered by puberty hormones but also in adults."],"dp":[]},"term1-skin:e5":{"s":2,"u":["Comedo: closed = whitehead; open = blackhead.","Comedo (plural comedones): non-infected lesion of sebum and keratin in a follicle; closed = whitehead, open (oxidised plug) = blackhead."],"dp":[{"h":"Why blackheads are black","t":"A blackhead is not dirt: it is an open comedo whose sebum and keratin plug is exposed to air, where it oxidises and darkens. A whitehead is the same plug under a closed opening, so it stays pale. One word, comedo, covers both, and the open/closed distinction explains the colour. Source: the lecture's pathology slide."}]},"term1-skin:e6":{"s":2,"u":["Seborrhea = excess sebum.","Seborrhea : excessive sebum (seb/o + -rrhea)."],"dp":[]},"term1-skin:e7":{"s":2,"u":["Macule: flat < 1 cm; papule: small raised; crust: dried serum.","Lesions: crust (dried serum and debris), macule (flat discoloured lesion under 1 cm), papule (small solid raised lesion)."],"dp":[]}},"meta":{"1niupn7":{"a":"recall","vg":"term1-skin:e0/recall/1"},"z2s5iv":{"a":"recall","vg":"term1-skin:e0/recall/2"},"1wjye1d":{"a":"recall","vg":"term1-skin:e1/recall/1"},"11u8qj0":{"a":"recall","vg":"term1-skin:e2/recall/1"},"da49v8":{"a":"recall","vg":"term1-skin:e6/recall/1"},"cljike":{"a":"recall","vg":"term1-skin:e2/recall/2"},"er0jre":{"a":"recall","vg":"term1-skin:e3/recall/1"},"1ihuwqo":{"a":"recall","vg":"term1-skin:e3/recall/2"},"12uhn7d":{"a":"recall","vg":"term1-skin:e3/recall/3"},"19emseg":{"a":"recall","vg":"term1-skin:e3/recall/4"},"tjpw7k":{"a":"recall","vg":"term1-skin:e5/recall/1"},"1ynl1xi":{"a":"recall","vg":"term1-skin:e6/recall/2"},"3l9ap1":{"a":"recall","vg":"term1-skin:e7/recall/1"},"1horciy":{"a":"recall","vg":"term1-skin:e0/recall/3"},"zapzcs":{"a":"recall","vg":"term1-skin:e2/recall/3"}},"explRev":"cf4cf6c09003"};
